  'δεσμος','θεσμος','χρησμος','σπασμος','κοσμος','κρουσμος','συνδεσμος',
  'Λακμος','Δεκμος','Τρωκμος','ποτμος','Πατμος','Λατμος','ατμος',
  'οφθαλμος','ψαλμος','παλμος','κορμος','θερμος','ορμος','Βρυσμος'
];

