 if(!token)return {norm:'—',kind:'—',preview:'—',why:'Type one Greek word ending in -μος.'};
 if(/\s/.test(token))return {norm:token,kind:'One word at a time',preview:'—',why:'Enter one Greek word; phrases are not concatenated.'};
 const k=key(token);
