 let kind='Unknown in this passage',why='No cited example or qualified cluster rule matches. No accent is inferred.';
 if(pre==='κ'||pre==='τ'){
  kind='Barytone pattern (nonfinal accent)';why='The passage gives barytone -'+pre+'μος forms, with named oxytone exceptions. A precise nonfinal accent is not inferred.';
 }else if(['σ','λ','ρ'].includes(pre)){
